    param()

    Write-Verbose 'Getting privileged role definitions and assignments...'
    $globalAdminId = '62e90394-69f5-4237-9190-012177145e10'
    $privilegedRoles = Invoke-MtGraphRequest -RelativeUri 'roleManagement/directory/roleDefinitions' -ApiVersion beta -Filter 'isPrivileged eq true'
    $instances = Invoke-MtGraphRequest -RelativeUri 'roleManagement/directory/roleAssignmentScheduleInstances' -QueryParameters @{ expand = 'principal' }

    $emergencyIds = @(Get-MtEmergencyAccessAccount | ForEach-Object { $_.ObjectId })
    $emergencyCandidates = 0
    $report = foreach ($instance in $instances) {
        $role = @($privilegedRoles) | Where-Object { $_.id -eq $instance.roleDefinitionId } | Select-Object -First 1
        if (-not $role) {
            continue
        }
        $principalType = $instance.principal.'@odata.type'
        $isEmergencyCandidate = $false
        if ($principalType -eq '#microsoft.graph.user' -or $principalType -eq '#microsoft.graph.group') {
            $compliant = $instance.assignmentType -eq 'Activated'
            # Only a permanent Global Administrator assignment to a user account can be an emergency access account.
            $isListedEmergencyAccount = $emergencyIds -contains $instance.principalId
            if ($principalType -eq '#microsoft.graph.user' -and $role.id -eq $globalAdminId -and $instance.assignmentType -eq 'Assigned' -and $null -eq $instance.endDateTime -and $isListedEmergencyAccount) {
                $isEmergencyCandidate = $true
                $emergencyCandidates++
                $compliant = $true
            }
        } elseif ($principalType -eq '#microsoft.graph.servicePrincipal') {
            $compliant = $instance.assignmentType -eq 'Assigned' -and $null -ne $instance.endDateTime
        } else {
            $compliant = $false
        }
        [pscustomobject]@{
            Role = $role.displayName
            Principal = if ($instance.principal.userPrincipalName) { $instance.principal.userPrincipalName } else { $instance.principal.displayName }
            PrincipalType = ($principalType -replace '#microsoft.graph.', '')
            AssignmentType = $instance.assignmentType
            EmergencyCandidate = $isEmergencyCandidate
            Pass = $compliant
        }
    }
    $failed = @($report | Where-Object { -not $_.Pass })
    $testResult = $failed.Count -eq 0 -and $emergencyCandidates -le 2

    $passText = 'Privileged roles are activated through PIM and not permanently assigned.'
    $failText = if ($failed.Count -gt 0) { "$($failed.Count) privileged role assignment(s) are not activated." } else { "$emergencyCandidates listed emergency access accounts hold permanent Global Administrator assignments. At most 2 are accepted." }

    $resultMd = "| Role | Principal | Type | Assignment | Result |`n"
    $resultMd += "| --- | --- | --- | --- | --- |`n"
    foreach ($row in ($report | Sort-Object -Property Pass, Role | Select-Object -First 100)) {
        $resultMd += "| $($row.Role) | $($row.Principal) | $($row.PrincipalType) | $($row.AssignmentType)$(if ($row.EmergencyCandidate) { ' (emergency access candidate)' }) | $(if ($row.Pass) { '✅ Pass' } else { '❌ Fail' }) |`n"
    }
    if (@($report).Count -gt 100) {
        $resultMd += "`nShowing 100 of $(@($report).Count) assignments."
    }

    if ($testResult) {
        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
    } else {
        $testResultMarkdown = "$failText Permanent Global Administrator assignments are accepted only for accounts listed in EmergencyAccessAccounts in maester-config.json. For how to configure it, see [Emergency access accounts](https://maester.dev/docs/configuration/emergency-access-accounts).`n`n%TestResult%"
    }
    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd

    Add-MtTestResultDetail -Result $testResultMarkdown
    return $testResult
}
== tests/maester/global-secure-access/Test.MT.1191.ps1
    param ()

    Write-Verbose "Running Test-MtGsaCompliantNetworkBreakGlassExcluded..."

    $compliantNetworkPolicies = Get-MtCompliantNetworkPolicy
    if (-not $compliantNetworkPolicies) {
        Add-MtTestResultDetail -Result 'No enabled Compliant Network enforcement policy was found, so there is nothing to evaluate.'
        return $null
    }

    $emergencyAccounts = Get-MtEmergencyAccessAccount
    if (-not $emergencyAccounts) {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason 'No emergency access accounts are configured in maester-config.json (EmergencyAccessAccounts), so break-glass exclusion cannot be verified.'
        return $null
    }

    # Resolve the parent groups each break-glass account belongs to (transitively), so an account
    # excluded via (nested) group membership - not just a direct user/group exclusion - is correctly
    # recognised. Both user and group accounts are resolved (a break-glass group can itself be a
    # member of an excluded group). Graph failures propagate to the outer catch so the check reports
    # an indeterminate result rather than a false pass.
    $accountGroupIds = @{}
    foreach ($account in $emergencyAccounts) {
        $endpoint = if ($account.Type -eq 'group') { "groups/$($account.ObjectId)/transitiveMemberOf" } else { "users/$($account.ObjectId)/transitiveMemberOf" }
        $memberOf = Invoke-MtGraphRequest -RelativeUri $endpoint -Select 'id' -ErrorAction Stop
        $accountGroupIds[$account.ObjectId] = @($memberOf.id)
    }

    $policiesMissingExclusion = @()
    foreach ($policy in $compliantNetworkPolicies) {
        $excludeUsers  = @($policy.conditions.users.excludeUsers)
        $excludeGroups = @($policy.conditions.users.excludeGroups)

        $uncovered = @()
        foreach ($account in $emergencyAccounts) {
            $id = $account.ObjectId
            $directlyExcluded = ($id -in $excludeUsers) -or ($id -in $excludeGroups)
            $excludedViaGroup = @($accountGroupIds[$id] | Where-Object { $_ -in $excludeGroups }).Count -gt 0
            if (-not ($directlyExcluded -or $excludedViaGroup)) {
                $uncovered += $account.DisplayName
            }
        }

        if ($uncovered.Count -gt 0) {
            $policiesMissingExclusion += [pscustomobject]@{ DisplayName = $policy.displayName; Uncovered = ($uncovered -join ', ') }
        }
    }

    $result = ($policiesMissingExclusion.Count -eq 0)
    if ($result) {
        $testResult = "Well done. Every Compliant Network enforcement policy excludes the emergency access (break-glass) accounts (directly or via an excluded group).`n`n"
    } else {
        $testResult = "These Compliant Network enforcement policies do **not** exclude all break-glass accounts (directly or via an excluded group) - lock-out risk:`n`n| Policy | Not excluded |`n| --- | --- |`n"
        foreach ($policy in $policiesMissingExclusion) {
            $testResult += "| $(Get-MtSafeMarkdown $policy.DisplayName) | $($policy.Uncovered) |`n"
        }
    }

    Add-MtTestResultDetail -Result $testResult
    return $result
}
